using FloppyUtils.SourceGen.Ext.Extensions;
using FloppyUtils.SourceGen.Ext.Helpers;
using FloppyUtils.SourceGen.Helpers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace FloppyUtils.SourceGen.Generators;

[Generator]
public sealed class SpanOneOutGenerator : IIncrementalGenerator
{
    internal const string Attribute = "FloppyUtils.SourceGen.Attributes.SpanOneOutAttribute";

    private static readonly DiagnosticDescriptor ErrSigUnexpectedParams = new(
        $"FloppyUtils.SourceGen.SpanOneOut.{nameof(ErrSigUnexpectedParams)}",
        "Unexpected params in signature",
        "The method should contain a single Span<T> parameter",
        "", DiagnosticSeverity.Error, true
    );

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var infos = context.SyntaxProvider.ForAttributeWithMetadataName(
            Attribute,
            static (node, _) => node is MethodDeclarationSyntax,
            static (context, token) => context.TargetSymbol is IMethodSymbol symbol ? Parse(context, symbol, token) : default
        ).Where(i => i != default);

        context.RegisterSourceOutput(
            infos,
            static (context, item) =>
            {
                if (item.Item1 is { } diag)
                {
                    context.ReportDiagnostic(diag.Create());
                }

                if (item.Item2 is { } info)
                {
                    context.AddSource($"{info.Hierarchy.FullName}.{info.Name}.SpanOneOut.g.cs", Generate(info, context.CancellationToken));
                }
            }
        );
    }

    internal static (DiagnosticInfo?, Info?) Parse(in GeneratorAttributeSyntaxContext context, IMethodSymbol symbol, CancellationToken token)
    {
        using var methods = new ImmutableArrayBuilder<(MethodReturn, string, int, EquatableArray<MethodParam>)>();

        (int, string?) span = default;

        var args = symbol.Parameters;
        for (int i = 0; i < args.Length; i++)
        {
            var arg = args[i];
            if (arg.Type is not INamedTypeSymbol { IsGenericType: true } type ||
                !type.Name.StartsWith("Span"))
            {
                continue;
            }

            if (span != default)
            {
                return (
                    ErrSigUnexpectedParams.ToInfo(context.TargetNode.GetLocation().ToInfo()),
                    null
                );
            }

            span = (i, type.TypeParameters[0].GetNameWithContainingTypeAndNamespace());
        }

        if (span == default)
        {
            return (
                ErrSigUnexpectedParams.ToInfo(context.TargetNode.GetLocation().ToInfo()),
                null
            );
        }

        Info proxy = new(
            symbol.ContainingType.GetHierarchy(),
            symbol.IsStatic,
            symbol.IsReadOnly,
            symbol.GetMethodReturn(),
            symbol.Name,
            symbol.GetMethodParams(),
            span!
        );

        return (
            null,
            proxy
        );
    }

    internal static string Generate(Info info, CancellationToken token)
    {
        using var writer = new IndentedTextWriter();
        writer.WriteLine("// <auto-generated/>");
        writer.WriteLine("#nullable enable");

        using (writer.BeginHierarchy(info.Hierarchy))
        {
            writer.Write("public ");
            if (info.IsStatic)
            {
                writer.Write("static ");
            }
            if (info.IsReadOnly)
            {
                writer.Write("readonly ");
            }
            writer.Write("unsafe ");
            writer.WriteSigReturnType(info.Return);
            writer.Write(" ");
            writer.Write(info.Name);
            writer.Write("(");

            for (int i = 0; i < info.Params.Length; i++)
            {
                if (i != info.Span.Index)
                {
                    writer.WriteSigParam(info.Params[i]);
                }
                else
                {
                    writer.Write("out ");
                    writer.Write(info.Span.Type);
                    writer.Write(" value");
                }

                if (i !=  info.Params.Length - 1)
                {
                    writer.Write(", ");
                }
            }

            writer.WriteLine(")");
            writer.WriteLine("{");
            writer.IncreaseIndent();

            writer.Write("fixed (");
            writer.Write(info.Span.Type);
            writer.WriteLine("* valuePtr = &value)");
            writer.WriteLine("{");
            writer.IncreaseIndent();

            writer.WriteReturnValue(info.Return);
            writer.Write(info.Name);
            writer.Write("(");

            for (int i = 0; i < info.Params.Length; i++)
            {
                if (i != info.Span.Index)
                {
                    writer.WriteCallParam(info.Params[i]);
                }
                else
                {
                    writer.Write("new(valuePtr, 1)");
                }

                if (i != info.Params.Length - 1)
                {
                    writer.Write(", ");
                }
            }

            writer.WriteLine(");");

            writer.DecreaseIndent();
            writer.WriteLine("}");

            writer.DecreaseIndent();
            writer.WriteLine("}");
        }

        return writer.ToString();
    }

    internal sealed record class Info(
        Hierarchy Hierarchy,
        bool IsStatic,
        bool IsReadOnly,
        MethodReturn Return,
        string Name,
        EquatableArray<MethodParam> Params,
        (int Index, string Type) Span
    );
}
